function day(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function touch(){if(!state.days.includes(day()))state.days.push(day());save()}
function streak(){const dates=[...new Set(state.days)].sort().reverse();if(!dates.length)return 0;let n=0,t=new Date(day()+'T12:00:00Z');if(dates[0]!==day())t.setUTCDate(t.getUTCDate()-1);for(const d of dates){if(d!==t.toISOString().slice(0,10))break;n++;t.setUTCDate(t.getUTCDate()-1)}return n}
