function shell(){const [page]=route();const nav=[['dashboard','grid','Dashboard'],['course','book','My course'],['modules','layers','Learning path'],['study','bulb','Continue learning'],['practice','target','Practice'],['exams','exam','Exams'],['mock','clock','Mock exams'],['mistakes','error','My mistakes'],['analytics','chart','Progress & analytics'],['flashcards','cards','Flashcards'],['compare','compare','Compare concepts'],['revision','check','Final revision']];const active=page==='lesson'?'course':page==='session'?(session?.strict?'exams':'practice'):page;document.body.classList.toggle('dark',state.dark);document.body.classList.toggle('focus-mode',state.focus);document.body.classList.toggle('sidebar-collapsed',!!state.sidebarCollapsed);document.body.classList.toggle('exam-active',page==='session'&&!!session?.strict&&!session.finished);$('#app').innerHTML=`<div class="mobile-backdrop" id="backdrop"></div><aside class="sidebar"><a class="brand" href="#dashboard" aria-label="Axiom learning dashboard"><span class="brand-mark">a<span>•</span></span><span>Axiom<small>HCIA-AI LEARNING WORKSPACE</small></span></a><div class="sidebar-course-progress"><div><span>COURSE PROGRESS</span><strong>${percentage(state.completed.length,lessons.length)}%</strong></div>${progressBar(percentage(state.completed.length,lessons.length))}<small>${state.completed.length} / ${lessons.length} sections completed</small></div><div class="nav-label">LEARN</div>${nav.slice(0,4).map(([r,i,t])=>navItem(r,i,t,active)).join('')}<div class="nav-label">PUT IT TO WORK</div>${nav.slice(4).map(([r,i,t])=>navItem(r,i,t,active)).join('')}<div class="sidebar-bottom"><div class="exam-card"><div class="eyebrow">YOUR CERTIFICATION</div><strong>Huawei HCIA-AI V4.0</strong><p>H13-311 · 6 exam domains</p><a href="#revision">View exam essentials ${icon('arrow')}</a></div><button class="nav-item ${active==='settings'?'active':''}" data-go="settings" aria-label="Settings">${icon('settings')} <span class="nav-text">Settings</span></button><div class="profile"><span class="avatar">${esc(state.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(state.name)}</strong><div class="muted">Personal learning workspace</div></div></div></div></aside><div class="main"><header class="topbar"><button class="round-btn mobile-toggle" id="mobileMenu" aria-label="Open navigation">${icon('menu')}</button><button class="round-btn desktop-collapse" data-action="sidebar" aria-label="Collapse or expand sidebar" aria-expanded="${!state.sidebarCollapsed}">${icon("menu")}</button><span class="topbar-title">${esc(nav.find(x=>x[0]===active)?.[2]||'Your learning workspace')}</span><label class="searchbox">${icon('search')}<input id="globalSearch" placeholder="Search topics, terms, questions…" aria-label="Search course" value="${page==='search'?esc(query):''}"><span class="kbd">⌘ K</span></label><button class="round-btn" data-action="theme" aria-label="Toggle light or dark mode">${icon('sun')}</button><span class="avatar">${esc(state.name.slice(0,1).toUpperCase())}</span></header><main id="view" class="content"></main><nav class="mobile-dock" aria-label="Quick navigation"><a href="#dashboard">${icon('home')}<span>Desk</span></a><a href="#course">${icon('book')}<span>Learn</span></a><a href="#practice">${icon('target')}<span>Practice</span></a><a href="#exams">${icon('exam')}<span>Exams</span></a><a href="#analytics">${icon('chart')}<span>Progress</span></a></nav></div>`;renderView();bindShell()}
function navItem(r,i,t,active){return `<a class="nav-item ${active===r?'active':''}" href="#${r}" title="${t}" ${active===r?'aria-current="page"':''}>${icon(i)}<span class="nav-text">${t}</span>${r==='mistakes'&&state.attempts.some(a=>!a.correct)?`<span class="count">${state.attempts.filter(a=>!a.correct).length}</span>`:''}</a>`}
