function moduleCard(m){const ls=lessons.filter(l=>l.module===m.id),done=ls.filter(l=>state.completed.includes(l.id)).length,p=percentage(done,ls.length),next=ls.find(l=>!state.completed.includes(l.id))||ls[0];return `<article class="module-card"><div class="module-card-top"><span class="module-icon">${icon(moduleIcons[m.id-1])}</span><span class="weight">${m.weight}% of exam</span></div><div class="eyebrow">MODULE ${String(m.id).padStart(2,'0')}</div><h3>${esc(m.title)}</h3><div class="module-meta"><span>${ls.length} sections · PDF ${m.pages.join('–')}</span><span>${p}%</span></div>${progressBar(p)}<div class="module-bottom"><span class="muted">${done} of ${ls.length} completed</span><a href="#lesson/${next.id}">${done?'Continue':'Start module'} →</a></div></article>`}
function dashboardOriginal(){const r=readiness(state,lessons,modules),n=lessons.find(l=>l.id===state.current)||nextLesson(),correct=state.attempts.filter(a=>a.correct).length;const weak=topicStats(state.attempts,lessons).filter(x=>x.total>=3&&x.accuracy<80).sort((a,b)=>a.accuracy-b.accuracy).slice(0,3);return `${header(`Welcome back, ${esc(state.name)}`,'Your next step toward AI certification starts here.',`<span class="pill">${icon('fire')} ${streak()} day study streak</span>`)}<section class="hero"><span class="hero-pattern"></span><div><div class="eyebrow">YOUR PATH TO HUAWEI CERTIFICATION</div><h2>A little progress today.<br>A stronger foundation tomorrow.</h2><p>Learn the concepts. Put them into practice.<br>Build confidence for your HCIA-AI V4.0 exam.</p><div class="actions"><a class="btn" href="#lesson/${n.id}">Continue learning ${icon('arrow')}</a><button class="btn secondary" data-action="diagnostic">Take diagnostic test</button></div></div>${art()}</section><section class="stats">${stat('Course completion',r.coverage+'%',`${state.completed.length} of ${lessons.length} sections completed`,'book')}${stat('Questions solved',state.attempts.length,`${correct} correct · ${state.attempts.length-correct} to review`,'target')}${stat('Overall accuracy',state.attempts.length?accuracy(state.attempts)+'%':'—',state.attempts.length?'Based on your recorded answers':'Answer a question to get started','check')}${stat('Study time',Math.floor(state.seconds/60)+' min',`${state.exams.length} exam${state.exams.length===1?'':'s'} completed`,'clock')}</section><div class="grid-main"><div><section class="panel"><div class="panel-head"><h2>Your learning path</h2><a class="link-btn" href="#course">View full course →</a></div><div class="module-grid">${modules.map(moduleCard).join('')}</div></section><section><div class="panel-head"><h2>Make your next move</h2><span class="muted small">Practice with purpose</span></div><div class="quick-grid"><button class="quick-action" data-go="practice">${icon('target')}Practice questions</button><button class="quick-action" data-go="exams">${icon('exam')}Take module exam</button><button class="quick-action" data-go="mock">${icon('clock')}Full mock exam</button><button class="quick-action" data-go="mistakes">${icon('error')}Review mistakes</button><button class="quick-action" data-go="flashcards">${icon('cards')}Flip flashcards</button><button class="quick-action" data-go="revision">${icon('check')}Final revision</button></div></section></div><aside><section class="panel readiness"><div class="panel-head"><h2>Exam readiness</h2><span class="tag">ESTIMATE</span></div><div class="gauge" style="--p:${r.score}"><div class="gauge-text"><strong>${r.score}<span style="font-size:16px;color:var(--muted)"> /100</span></strong><small>readiness score</small></div></div><span class="status-label">${r.label}</span><p>${state.attempts.length?'Keep building evidence across every domain, including hard questions and timed mocks.':'Start with the diagnostic to discover what you know and what to study next.'}</p><button class="btn soft" data-action="${state.attempts.length?'weakness':'diagnostic'}">${state.attempts.length?'Practice weak areas':'Assess my starting point'} ${icon('arrow')}</button><div class="confidence">Preparation indicator only.<br>It does not guarantee an exam result.</div></section><section class="panel"><div class="panel-head"><h2>Pick up where you left off</h2></div><a class="next-card" href="#lesson/${n.id}"><span class="small-icon">${icon('book')}</span><div><span class="eyebrow">MODULE ${String(n.module).padStart(2,'0')}</span><br><strong>${esc(n.title)}</strong><p>${n.concepts.length} key concepts · guided lesson</p></div></a><a class="link-btn" href="#lesson/${n.id}">Open lesson →</a></section><section class="panel"><div class="panel-head"><h2>Your focus areas</h2>${icon('target')}</div>${weak.length?weak.map(w=>`<a class="next-card" href="#lesson/${w.id}"><div><strong>${esc(w.title)}</strong><p>${w.accuracy}% accuracy · ${w.total} answers</p></div></a>`).join(''):empty('Your weak topics will appear after at least 3 answers in a section.','chart')}</section></aside></div>${footer()}`}
