const codes={s19:`import torch\nfrom torch import nn\nfrom torch.utils.data import DataLoader\n\n# model is an nn.Module; trainset supplies inputs and labels\nloader = DataLoader(trainset, batch_size=64, shuffle=True)\ncriterion = nn.CrossEntropyLoss()\noptimizer = torch.optim.SGD(model.parameters(), lr=0.01)\n\nmodel.train()\nfor inputs, labels in loader:\n    optimizer.zero_grad()\n    outputs = model(inputs)\n    loss = criterion(outputs, labels)\n    loss.backward()\n    optimizer.step()\n\ntorch.save(model.state_dict(), 'model.pth')\nmodel.eval()\nwith torch.no_grad():\n    predictions = model(new_inputs)`,s18:`# NCHW: batch, channels, height, width\ninputs = torch.randn(8, 3, 32, 32)\nlayer = nn.Conv2d(3, 16, kernel_size=3, stride=1, padding=0)\noutputs = layer(inputs)\n# outputs.shape: [8, 16, 30, 30]`,s14:`# RNN with batch_first=True\nrnn = nn.RNN(input_size=10, hidden_size=20, batch_first=True)\ninputs = torch.randn(5, 3, 10)\noutputs, hidden = rnn(inputs)\n# 5 samples, 3 time steps, 10 input features\n# outputs.shape: [5, 3, 20]`};
const diagrams={s1:['AI','Machine learning','Deep learning'],s8:['Prepare data','Engineer features','Train & validate','Test','Deploy & iterate'],s11:['Inputs','Weighted sum + bias','Nonlinear activation','Output'],s12:['Forward','Loss','Backward gradients','Optimizer update'],s13:['Image','Convolution + activation','Pooling','Flatten & classify'],s14:['Input + old state','RNN / LSTM','New state','Output'],s15:['Query ↔ Keys','Relevance scores','Softmax weights','Weighted Values'],s16:['Input','Gate / routing','Selected experts','Combined output'],s19:['Clear gradients','Forward','Loss','Backward','Step'],s20:['Requirement','Data & network','Train & test','Deploy'],s21:['Business need','Collect & prepare','Select & train','Evaluate','Deploy'],s22:['Pretrain','Supervised fine-tune','Reward model','RL optimization','Evaluate'],s26:['Road sensing','Driving support','Cockpit interaction'],s27:['User interest','Entity relations','Candidate items','Recommendations'],s28:['Vision','Language','Action'],s29:['Scientific problem','Data representation','AI model','Scientific validation']};
function diagram(l){const arr=diagrams[l.id];if(!arr)return '';return `<div class="diagram" aria-label="Concept flow">${arr.map((x,i)=>`${i?'<span class="diagram-arrow">→</span>':''}<span class="diagram-node">${esc(x)}</span>`).join('')}</div><div class="small muted">Conceptual study aid derived from this section; open the source PDF for the original architecture diagrams.</div>${l.id==='s15'?`<div class="chart-grid mt"><div class="example"><strong>Encoder stack</strong><p>Input embedding + position → multi-head self-attention → Add & Norm → feed-forward → Add & Norm.</p></div><div class="example"><strong>Decoder stack</strong><p>Output embedding + position → masked self-attention → encoder-decoder attention → feed-forward → linear + softmax. Residual Add & Norm connections surround the sublayers.</p></div></div>`:''}`}
function lessonOriginal(id,guided=false){const l=lessons.find(l=>l.id===id)||nextLesson(),i=lessons.indexOf(l),m=modules[l.module-1],a=state.attempts.filter(a=>a.section===l.id),complete=state.completed.includes(l.id);return `<div class="breadcrumb"><a href="#course">Course</a> / <a href="#course/${m.id}">Module ${String(m.id).padStart(2,'0')}</a> / ${esc(l.title)}</div>${header(esc(l.title),`${esc(m.title)} · PDF pages ${l.pages.join('–')}`,`<button class="btn secondary small" data-action="focus">${icon('book')} ${state.focus?'Exit focus':'Focus mode'}</button>`)}${guided?`<div class="study-steps">${['1 Explanation','2 Example','3 Key concepts','4 Exam focus','5 Practice','6 Review','7 Complete'].map((s,i)=>`<span class="${i===0?'on':''}">${s}</span>`).join('')}</div>`:''}<div class="lesson-layout"><article class="panel lesson-body"><div class="actions"><span class="tag">MODULE ${String(m.id).padStart(2,'0')}</span><span class="tag ${complete?'green':''}">${complete?'Completed':'In progress'}</span><button class="btn secondary small" data-action="arabic">Explain in Arabic</button></div><div id="arabic" class="arabic hidden mt" lang="ar">${esc(l.arabic)}</div><div class="objectives"><strong>Learning objectives</strong><ul>${l.concepts.map(c=>`<li>Explain ${esc(c.term.toLowerCase())} and recognize its use in an exam scenario.</li>`).join('')}</ul></div><h2 id="explanation">The idea, simply</h2><p>${esc(l.intro)}</p>${diagram(l)}<h2 id="concepts">Understand the details</h2>${l.concepts.map(c=>`<div class="concept"><h3>${esc(c.term)}</h3><p>${esc(c.explanation)}</p></div>`).join('')}<h2 id="example">Make it concrete</h2><div class="example"><span class="eyebrow">WORKED EXAMPLE</span><p>${esc(l.example)}</p></div>${codes[l.id]?`<h2>Read the code</h2><p class="small muted">Study adaptation of the course example. This is a code-reading aid; variables such as model and datasets must be created in a complete program.</p><pre class="code">${esc(codes[l.id])}</pre><h3>What should I understand from this code?</h3><p>${l.id==='s19'?'DataLoader creates batches. zero_grad clears gradients, backward calculates them and step updates weights. Saving state_dict stores model state, not the class definition. eval and no_grad serve different purposes.':l.id==='s14'?'batch_first=True puts batch size before sequence length. Read the actual function arguments rather than relying on a conflicting comment. The output has one hidden vector per input time step.':'The second dimension is the channel count. Sixteen filters produce sixteen output channels. A 3×3 kernel without padding changes a 32×32 spatial input to 30×30.'}</p>`:''}<section class="exam-focus" id="focus"><h3>EXAM FOCUS</h3><strong>Remember</strong><ul>${l.concepts.slice(0,3).map(c=>`<li>${esc(c.explanation)}</li>`).join('')}</ul><strong>Common trap</strong><p>${esc(l.trap)}</p><strong>Memory rule</strong><p style="margin:4px 0">${esc(l.memory)}</p></section><h2>Key terminology</h2><div class="actions">${l.concepts.map(c=>`<span class="tag">${esc(c.term)}</span>`).join('')}</div><h2 id="check">Check your understanding</h2><div class="check-understanding"><p>Can you explain the difference between <strong>${esc(l.concepts[0].term)}</strong> and <strong>${esc(l.concepts[1].term)}</strong> without looking above?</p><details><summary>Compare your explanation</summary><p>${esc(l.concepts[0].explanation)} ${esc(l.concepts[1].explanation)}</p></details></div><h2 id="practice">Practice this section</h2><p class="muted small">5 questions · immediate feedback · a mix of formats · ${a.length?a.length+' recorded attempts, '+accuracy(a)+'% accuracy':'no attempts yet'}</p><div class="actions"><button class="btn" data-action="practice-section:${l.id}">Practice 5 questions ${icon('arrow')}</button><button class="btn secondary" data-action="section-exam:${l.id}">Take 10-question test</button></div><h2 id="source">Go deeper in the primary source</h2><p class="muted small">The explanations above are study summaries. Read all slides in this section for additional named algorithms, numbers, tables and diagrams. These details remain part of the course.</p><a class="btn secondary small" href="training-material.pdf#page=${l.pages[0]}" target="_blank" rel="noopener">Open original pages ${l.pages.join('–')} ↗</a><button class="btn secondary small" data-action="source:${l.id}">Browse source slide text</button><div id="sourceText"></div>${l.id==='s15'?`<div class="confidence">[External Knowledge · architecture clarification] Source consistency note: the quiz key on PDF p.302 appears inconsistent with the original Transformer diagram on p.290. This platform teaches the architecture shown in the diagram and avoids grading the ambiguous wording.</div>`:''}<div class="source-note">Primary source: HCIA-AI V4.0 Training Material · PDF ${l.pages.join('–')}. The summary and questions are original study adaptations. The source viewer preserves original slide text, including any inconsistencies.</div><div class="actions mt"><button class="btn ${complete?'secondary':''}" data-action="complete:${l.id}">${icon('check')} ${complete?'Mark as not completed':'Mark as completed'}</button><span class="flex-spacer"></span>${i>0?`<a class="btn secondary small" href="#lesson/${lessons[i-1].id}">← Previous</a>`:''}${i<lessons.length-1?`<a class="btn secondary small" href="#lesson/${lessons[i+1].id}">Next topic →</a>`:`<a class="btn secondary small" href="#mock">Try a mock exam →</a>`}</div></article><aside class="lesson-aside"><div class="panel"><div class="eyebrow">IN THIS LESSON</div>${[['explanation','Simple explanation'],['concepts','Important concepts'],['example','Worked example'],['focus','Exam focus'],['check','Check understanding'],['practice','Practice this section'],['source','Primary source']].map(([a,b])=>`<a href="#${location.hash.slice(1)}" data-scroll="${a}">${b}</a>`).join('')}<div class="source-note">${l.concepts.length} key concepts<br>${a.length?accuracy(a)+'% practice accuracy':'Not yet assessed'}</div></div><div class="panel"><h3 style="font-size:13px">Make it stick</h3><p class="muted small">${esc(l.memory)}</p><button class="btn soft small" data-action="flash-section:${l.id}">Review flashcards</button></div></aside></div>`}
function moduleSelect(id='filterModule'){return `<select class="field" id="${id}" aria-label="Filter by module"><option value="all">All modules</option>${modules.map(m=>`<option value="${m.id}">Module ${m.id} · ${esc(m.title)}</option>`).join('')}</select>`}
function sectionSelect(){return `<select class="field" id="filterSection" aria-label="Select section"><option value="all">All sections</option>${lessons.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select>`}
function practice(){const due=Object.values(state.cards).filter(x=>x.due&&x.due<=Date.now()).length;return `${header('Practice with purpose','Small, focused sessions. Clear explanations. A stronger grasp of every concept.')}<div class="grid-main"><section class="panel"><span class="tag">PRACTICE BUILDER</span><h2 class="mt">What would you like to work on?</h2><p class="muted small">Choose your scope and difficulty. Answers stay hidden until you submit.</p><div class="form-grid"><label>Module${moduleSelect()}</label><label>Section${sectionSelect()}</label><label>Difficulty<select class="field" id="filterDifficulty"><option value="all">Mixed difficulty</option><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select></label><label>Questions<select class="field" id="practiceCount"><option>5</option><option>10</option><option>20</option></select></label></div><div class="actions mt"><button class="btn" data-action="practice-build">Start practice ${icon('arrow')}</button><button class="btn secondary" data-action="random">Random practice</button></div></section><aside><section class="panel"><h2>Review what matters</h2><p class="muted small">Weakness practice selects low-accuracy sections. Similar-question retests use a different item for the same concept when available.</p><button class="btn soft fullwidth" data-action="weakness">Practice weak areas</button><p class="muted small mt">${due} flashcards due for review</p><a class="btn secondary small" href="#flashcards">Open flashcards</a></section></aside></div><section class="panel"><h2>Practice by section</h2>${lessons.map(l=>`<div class="section-row"><span class="step-number">${l.module}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.memory)}</p></div><button class="btn secondary small right" data-action="practice-section:${l.id}">Practice →</button></div>`).join('')}</section>`}
function exams(){return `${header('Your exam center','Section tests, module exams and full simulations — separate from guided learning.')}<div class="exam-grid">${modules.map(m=>`<section class="panel exam-type"><span class="module-icon">${icon(moduleIcons[m.id-1])}</span><h3>Module ${m.id} exam</h3><p>${esc(m.title)}<br>20 questions · 30 minutes<br>${m.weight}% of official exam scope</p><button class="btn secondary small" data-action="module-exam:${m.id}">Start module exam →</button></section>`).join('')}</div><div class="exam-grid"><section class="panel exam-type"><span class="module-icon">${icon('clock')}</span><h3>Full mock exam</h3><p>60 questions · 90 minutes<br>Official domain weighting, original practice items. No feedback until submission.</p><button class="btn" data-action="mock">Start mock exam →</button></section><section class="panel exam-type"><span class="module-icon">${icon('target')}</span><h3>Weakness exam</h3><p>20 questions · 30 minutes<br>Built from sections where you have the lowest recorded accuracy.</p><button class="btn secondary" data-action="weakness-exam">Test weak areas →</button></section><section class="panel exam-type"><span class="module-icon">${icon('chart')}</span><h3>Diagnostic assessment</h3><p>40 questions · 60 minutes<br>All six modules. Assess your starting point without hints or immediate answers.</p><button class="btn secondary" data-action="diagnostic">Take diagnostic →</button></section></div><section class="panel"><h2>Section tests</h2><div class="filters">${sectionSelect()}<button class="btn secondary" data-action="section-exam-selected">Start 10-question test</button></div><p class="muted small">10 questions · 15 minutes · one selected section only.</p></section><section class="panel"><h2>Exam history</h2>${examHistory()}</section>`}
function mock(){return `${header('A rehearsal for exam day','Build confidence with a focused, timed simulation.')}<div class="grid-main"><section class="panel"><span class="tag">FULL HCIA-AI V4.0 SIMULATION</span><h2 class="mt">Put your preparation to the test.</h2><p class="muted">60 original practice questions · 90 minutes · mixed question types</p><div class="checklist"><label>${icon('check')} No hints, answers, explanations, topic names or difficulty labels during the exam</label><label>${icon('check')} Navigate previous / next, flag questions and review your responses</label><label>${icon('check')} Your timer and answers survive a refresh on this browser</label><label>${icon('check')} Submit once, then receive full results and concept-level feedback</label></div><h3 class="mt">Domain distribution</h3>${modules.map(m=>`<div class="chart-row"><span>Module ${m.id}</span>${progressBar(m.weight)}<span>${Math.round(60*m.weight/100)} Q</span></div>`).join('')}<div class="actions mt"><button class="btn" data-action="mock">Start full mock exam ${icon('arrow')}</button>${session?.strict?`<a class="btn secondary" href="#session">Resume active exam</a>`:''}</div><div class="source-note">This is a training simulation, not an official question set. The 60-question count is a platform choice. The official outline specifies 90 minutes and domain weights; it does not establish this platform question count.</div></section><aside><section class="panel"><h2>Before you begin</h2><p class="muted small">Find a quiet place. Read multi-answer instructions carefully. Blank responses count as incorrect. Fill-in responses use normalized exact matching with supported aliases.</p><p class="small">Target: 90% overall, at least 85% in major domains, strong hard-question results and few repeated errors.</p><div class="confidence">Readiness is an estimate. A high aggregate result can hide a weak domain.</div></section></aside></div><section class="panel"><h2>Your mock results</h2>${examHistory('mock')}</section>`}
function poolFor(lid){return bank.filter(q=>q.section===lid)}
function initialPractice(lid){const p=poolFor(lid);const ids=[lid+'-q1',lid+'-multi',lid+'-scenario',lid+'-tf',lid+'-r5'];return ids.map(id=>p.find(q=>q.question_id===id)).filter(Boolean)}
function startSession(qs,mode,title,minutes=0){if(session?.strict&&!session.finished){if(!confirm('An unfinished exam is active. Replace it with this new session?'))return}if(!qs.length){toast('No matching questions. Broaden your filters or answer questions to identify weak areas.');return}session={id:'run-'+Date.now(),mode,title,strict:mode!=='practice',questions:qs.map(prepareQuestion),index:0,answers:{},flags:[],recorded:{},start:Date.now(),deadline:minutes?Date.now()+minutes*60000:null};feedback=null;examReview=false;touch();save();go('session');if(route()[0]==='session')shell()}
function weakQuestions(count=20){const stats=topicStats(state.attempts,lessons).filter(x=>x.total>0).sort((a,b)=>a.accuracy-b.accuracy);if(!stats.length)return [];const target=new Set(stats.filter(s=>s.accuracy<85).map(s=>s.id));if(!target.size)return [];const wrongTopics=new Set(state.attempts.filter(a=>!a.correct).map(a=>a.topic));return shuffle(bank.filter(q=>target.has(q.section))).sort((a,b)=>(wrongTopics.has(b.topic)?1:0)-(wrongTopics.has(a.topic)?1:0)).slice(0,count)}
function sessionView(){if(!session)return `${header('No active session','Choose practice or an exam to begin.')}<a class="btn" href="#practice">Open practice</a>`;if(session.finished)return result(session.id);const q=session.questions[session.index];if(!q)return empty('This session has no questions.');const a=session.answers[session.index];const f=session.strict?null:session.recorded[session.index];const n=session.questions.length;const title=session.strict?'Exam in progress':session.title;return `<div class="question-wrap">${header(esc(title),session.strict?'Stay focused. Answers and explanations appear only after submission.':'Read carefully, choose your answer, then check your understanding.')}<div class="question-header"><span class="small muted">Question ${session.index+1} of ${n}</span>${session.strict?'<span class="timer" id="timer">--:--</span>':`<span class="tag">${esc(q.difficulty)} · Module ${q.module}</span>`}<button class="btn secondary small" data-action="flag">${icon('flag')} ${session.flags.includes(session.index)?'Flagged':'Flag'}</button></div>${progressBar(percentage(session.index,n))}<section class="panel"><div class="eyebrow">${q.question_type==='multiple'?'SELECT ALL CORRECT ANSWERS':q.question_type==='fill'?'FILL IN THE BLANK':q.question_type==='boolean'?'TRUE OR FALSE':'SELECT ONE ANSWER'}</div>${session.strict?'':`<div class="muted small">${esc(q.source_topic)}</div>`}<h2 class="question-title">${esc(q.question)}</h2>${q.code?`<pre class="code">${esc(q.code)}</pre>`:""}${q.question_type==='fill'?`<label class="small muted" for="fillAnswer">Your answer</label><input id="fillAnswer" class="field fullwidth" placeholder="Type the answer…" value="${esc(a||'')}" ${f?'disabled':''}><p class="muted small">Spelling and punctuation are normalized; unsupported synonyms may require review.</p>`:q.options.map((op,i)=>`<label class="option ${a?.includes(i)?'selected':''} ${f?(q.correct_answer.includes(i)?'correct':a?.includes(i)?'wrong':''):''}"><input name="answer" type="${q.question_type==='multiple'?'checkbox':'radio'}" value="${i}" ${a?.includes(i)?'checked':''} ${f?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(op)}</span></label>`).join('')}${f?feedbackHtml(q,f):''}<div class="actions mt">${session.strict?`<button class="btn secondary" data-action="prev" ${session.index===0?'disabled':''}>← Previous</button><span class="flex-spacer"></span>${session.index<n-1?`<button class="btn" data-action="next">Next question →</button>`:`<button class="btn" data-action="exam-review">Review & submit</button>`}`:f?`<button class="btn" data-action="practice-next">${session.index<n-1?'Next question →':'Finish practice'}</button>${!f.correct?`<button class="btn secondary" data-action="similar:${q.question_id}">Try a similar question</button>`:''}<a class="btn secondary" href="#lesson/${q.section}">Review topic</a>`:`<button class="btn" data-action="answer">Submit answer</button>`}</div></section>${session.strict?`<section class="panel"><div class="panel-head"><h2>Question navigator</h2><span class="muted small">${Object.values(session.answers).filter(answered).length}/${n} answered</span></div><div class="navigator">${session.questions.map((_,i)=>`<button class="navnum ${answered(session.answers[i])?'answered':''} ${session.index===i?'current':''} ${session.flags.includes(i)?'flag':''}" data-action="jump:${i}" aria-label="Question ${i+1}${session.flags.includes(i)?', flagged':''}">${i+1}</button>`).join('')}</div><div class="actions"><button class="btn secondary small" data-action="exam-review">Review questions</button><button class="btn small" data-action="finish-exam">Submit exam</button></div>${examReview?`<div class="feedback"><h3>Review before submitting</h3><p>${session.questions.filter((_,i)=>!answered(session.answers[i])).length} unanswered · ${session.flags.length} flagged</p><p>Use the navigator to review any response. Submission ends the exam and reveals your result.</p><button class="btn" data-action="finish-exam">Confirm final submission</button></div>`:''}</section>`:''}</div>`}
function feedbackHtml(q,f){return `<div class="feedback" role="status"><h3 style="color:${f.correct?'var(--green)':'var(--red)'}">${f.correct?'Correct ✓':'Incorrect ✕'}</h3><p><strong>Correct answer:</strong> ${q.question_type==='fill'?esc(q.correct_answer[0]):q.correct_answer.map(i=>String.fromCharCode(65+i)+' — '+esc(q.options[i])).join('; ')}</p><p>${esc(q.explanation)}</p>${q.options?.length?`<details open><summary>Understand every option</summary>${q.options.map((x,i)=>`<div class="why"><strong>${String.fromCharCode(65+i)} — ${q.correct_answer.includes(i)?'Correct':'Incorrect'}.</strong> ${esc(q.option_explanations?.[i]||q.explanation)}</div>`).join('')}</details>`:''}<p class="mt"><strong>EXAM TIP:</strong> ${esc(q.exam_tip)}</p>${!f.correct?`<p class="muted small">Review focus: ${q.question_type==='fill'?'terminology / recall':'concept distinction'} · ${esc(q.topic)}. Review the explanation to decide whether this was a knowledge gap or a misread.</p>`:''}<a class="small" href="training-material.pdf#page=${q.source_pages[0]}" target="_blank" rel="noopener">Source: ${esc(q.source_topic)} · PDF ${q.source_pages.join('–')} ↗</a></div>`}
function record(q,a,run){const attempt={id:'a-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),question_id:q.question_id,module:q.module,section:q.section,topic:q.topic,difficulty:q.difficulty,question_type:q.question_type,correct:evaluate(q,a),answer:a??null,question:q,at:Date.now(),session:run};state.attempts.push(attempt);if(!attempt.correct){const key=q.section+'|'+q.topic,prev=state.cards[key]||{level:0};state.cards[key]={...prev,known:false,level:0,due:Date.now()+86400000}}touch();return attempt}
function finishPractice(){const attempts=state.attempts.filter(a=>a.session===session.id);session.finished=true;session.score=accuracy(attempts);session.total=attempts.length;save();shell()}
function finishExam(force=false){const blanks=session.questions.filter((_,i)=>!answered(session.answers[i])).length;if(!force&&!confirm(`Submit this exam? ${blanks} unanswered question${blanks===1?'':'s'} will count as incorrect. Your result will be final.`))return;const attempts=session.questions.map((q,i)=>record(q,session.answers[i],session.id));const summary={id:session.id,title:session.title,mode:session.mode,score:accuracy(attempts),correct:attempts.filter(a=>a.correct).length,total:attempts.length,at:Date.now(),duration:Math.round((Date.now()-session.start)/1000),timedOut:force};state.exams.push(summary);session.finished=true;session.score=summary.score;save();shell()}
function result(id){const run=id||session?.id,attempts=state.attempts.filter(a=>a.session===run),exam=state.exams.find(e=>e.id===run),title=exam?.title||session?.title||'Session result',r=readiness(state,lessons,modules);if(!attempts.length)return empty('No results yet. Complete a practice session or an exam.');return `${header(esc(title)+' · Results',exam?'Exam submitted. Your responses are now final.':'Practice completed. Review your reasoning and choose the next step.')}<div class="grid-main"><section class="panel"><span class="eyebrow">YOUR SCORE</span><div class="result-score">${accuracy(attempts)}<span style="font-size:22px">%</span></div><p class="muted">${attempts.filter(a=>a.correct).length} correct out of ${attempts.length} · ${exam?Math.ceil(exam.duration/60)+' min':'Practice session'}</p><div class="actions"><a class="btn" href="#mistakes">Review mistakes →</a><a class="btn secondary" href="#analytics">View analytics</a><button class="btn secondary" data-action="weakness">Practice weak areas</button></div><h3 class="mt">Domain performance</h3>${modules.filter(m=>attempts.some(a=>a.module===m.id)).map(m=>{let a=attempts.filter(a=>a.module===m.id);return `<div class="chart-row"><span>Module ${m.id}</span>${progressBar(accuracy(a))}<span>${accuracy(a)}%</span></div>`}).join('')}<h3>Difficulty performance</h3><table class="progress-table"><thead><tr><th>Difficulty</th><th>Correct / total</th><th>Accuracy</th></tr></thead><tbody>${['easy','medium','hard'].map(d=>{let a=attempts.filter(x=>x.difficulty===d);return `<tr><td>${d}</td><td>${a.filter(x=>x.correct).length} / ${a.length}</td><td>${a.length?accuracy(a)+'%':'Not assessed'}</td></tr>`}).join('')}</tbody></table></section><aside><section class="panel"><h2>Estimated readiness</h2><div class="result-score" style="font-size:36px">${r.score}/100</div><span class="status-label">${r.label}</span><p class="small muted mt">${r.strongEvidence?'Strong evidence across the assessed domains. Keep revising repeated errors.':'NOT READY — REVIEW REQUIRED for a strong-readiness claim. Build evidence across all major modules, hard questions and at least two mocks.'}</p><p class="muted small">This score is a preparation indicator, not a promise of passing.</p></section></aside></div><section class="panel"><h2>Question-by-question review</h2>${attempts.map((a,i)=>`<details><summary>${i+1}. ${a.correct?'✓':'✕'} ${esc(a.question.question)}</summary>${a.question.code?`<pre class="code">${esc(a.question.code)}</pre>`:""}<p class="small"><strong>Your answer:</strong> ${formatAnswer(a.question,a.answer)}</p>${feedbackHtml(a.question,a)}</details>`).join('')}</section>`}
function formatAnswer(q,a){if(q.question_type==='fill')return esc(a||'Unanswered');return a?.length?a.map(i=>esc(q.options[i])).join('; '):'Unanswered'}
function examHistory(mode){const a=state.exams.filter(e=>!mode||e.mode===mode).slice().reverse();return a.length?`<table class="progress-table"><thead><tr><th>Exam</th><th>Date</th><th>Score</th><th>Result</th></tr></thead><tbody>${a.map(e=>`<tr><td>${esc(e.title)}</td><td>${new Date(e.at).toLocaleDateString()}</td><td>${e.score}%</td><td><a href="#result/${e.id}">Review →</a></td></tr>`).join('')}</tbody></table>`:empty('Your completed exams will appear here.','exam')}
function mistakes(){return `${header('Turn mistakes into understanding','Every incorrect response is saved. Revisit the concept, then try a different question.')}<section class="panel"><div class="filters">${moduleSelect()}${sectionSelect()}<select class="field" id="filterDifficulty"><option value="all">All difficulties</option><option>easy</option><option>medium</option><option>hard</option></select><select class="field" id="filterType"><option value="all">All question types</option><option value="single">Single choice</option><option value="multiple">Multiple answer</option><option value="boolean">True / false</option><option value="fill">Fill in the blank</option></select><select class="field" id="filterDate"><option value="all">All dates</option><option value="1">Last 24 hours</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option></select></div><div id="mistakeList">${mistakeList()}</div></section>`}
function mistakeList(){const f=id=>$('#'+id)?.value||'all';const a=state.attempts.filter(a=>!a.correct&&(f('filterModule')==='all'||a.module===Number(f('filterModule')))&&(f('filterSection')==='all'||a.section===f('filterSection'))&&(f('filterDifficulty')==='all'||a.difficulty===f('filterDifficulty'))&&(f('filterType')==='all'||a.question_type===f('filterType'))&&(f('filterDate')==='all'||Date.now()-a.at<=Number(f('filterDate'))*86400000)).slice().reverse();if(!a.length)return empty('No mistakes match this view. Begin practice to build your review list.','check');return a.map(a=>`<details class="source-slide"><summary>${esc(a.question.question)} <span class="tag red">${esc(a.difficulty)}</span></summary><p class="muted small">Module ${a.module} · ${esc(a.topic)} · ${new Date(a.at).toLocaleString()}</p>${a.question.code?`<pre class="code">${esc(a.question.code)}</pre>`:""}<p class="small"><strong>My answer:</strong> ${formatAnswer(a.question,a.answer)}</p>${feedbackHtml(a.question,a)}<div class="actions"><a class="btn secondary small" href="#lesson/${a.section}">Review topic</a><button class="btn small" data-action="similar:${a.question_id}">Try a similar question</button></div></details>`).join('')}
function analytics(){const r=readiness(state,lessons,modules),ts=topicStats(state.attempts,lessons).filter(t=>t.total),weak=ts.filter(t=>t.accuracy<85).sort((a,b)=>a.accuracy-b.accuracy),strong=[...ts].sort((a,b)=>b.accuracy-a.accuracy),mocks=state.exams.filter(e=>e.mode==='mock');return `${header('Your progress, made visible','Real learning data. Clear priorities. No invented scores.')}<div class="stats">${stat('Accuracy',state.attempts.length?accuracy(state.attempts)+'%':'—',state.attempts.length+' total answers','target')}${stat('Course progress',r.coverage+'%',state.completed.length+' completed sections','book')}${stat('Average exam score',state.exams.length?Math.round(state.exams.reduce((s,e)=>s+e.score,0)/state.exams.length)+'%':'—',state.exams.length+' completed exams','exam')}${stat('Readiness',r.score+'/100',r.label,'chart')}</div><div class="chart-grid"><section class="panel"><h2>Accuracy by module</h2>${modules.map(m=>{const a=state.attempts.filter(x=>x.module===m.id);return `<div class="chart-row"><span>Module ${m.id}<br><small class="muted">${a.length} answers</small></span>${progressBar(accuracy(a))}<span>${a.length?accuracy(a)+'%':'—'}</span></div>`}).join('')}</section><section class="panel"><h2>Learning coverage</h2>${modules.map(m=>{const ls=lessons.filter(l=>l.module===m.id),n=ls.filter(l=>state.completed.includes(l.id)).length;return `<div class="chart-row"><span>Module ${m.id}<br><small class="muted">${n}/${ls.length} sections</small></span>${progressBar(percentage(n,ls.length))}<span>${percentage(n,ls.length)}%</span></div>`}).join('')}</section><section class="panel"><h2>Mock exam scores</h2>${mocks.length?`<svg class="chart-svg" viewBox="0 0 500 180" aria-label="Mock scores"><path d="M30 10V155H480" stroke="var(--border)" fill="none"/>${[0,50,100].map(v=>`<text x="0" y="${155-v*1.35}" font-size="10" fill="var(--muted)">${v}</text><path d="M30 ${155-v*1.35}H480" stroke="var(--border)"/>`).join('')}<polyline class="score-line" points="${mocks.slice(-10).map((m,i,a)=>`${35+i*(430/Math.max(1,a.length-1))},${155-m.score*1.35}`).join(' ')}"/>${mocks.slice(-10).map((m,i,a)=>`<circle cx="${35+i*(430/Math.max(1,a.length-1))}" cy="${155-m.score*1.35}" r="4" fill="var(--primary)"><title>${m.score}% · ${new Date(m.at).toLocaleDateString()}</title></circle>`).join('')}</svg>`:empty('Complete a mock exam to see your score trend.','chart')}</section><section class="panel"><h2>Questions by outcome</h2>${state.attempts.length?`<div class="gauge" style="--p:${accuracy(state.attempts)}"><div class="gauge-text"><strong>${state.attempts.length}</strong><small>recorded answers</small></div></div><div class="chart-legend"><span>● ${state.attempts.filter(a=>a.correct).length} correct</span><span>○ ${state.attempts.filter(a=>!a.correct).length} incorrect</span></div>`:empty('Your answers will populate this chart.','target')}</section></div><div class="chart-grid"><section class="panel"><h2>Weakest sections</h2>${weak.length?weak.slice(0,10).map(t=>`<div class="section-row"><div><h3>${esc(t.title)}</h3><p>${t.accuracy}% · ${t.total} answers${t.total<3?' · limited evidence':''}</p></div><a class="btn soft small right" href="#lesson/${t.id}">Study</a></div>`).join(''):empty('No assessed section below 85%. Assess more topics to build confidence.')}</section><section class="panel"><h2>Strongest sections</h2>${strong.length?strong.slice(0,10).map(t=>`<div class="section-row"><div><h3>${esc(t.title)}</h3><p>${t.accuracy}% · ${t.total} answers${t.total<3?' · limited evidence':''}</p></div></div>`).join(''):empty('No topics assessed yet.')}</section></div><section class="panel"><h2>Accuracy by question type</h2><table class="progress-table"><thead><tr><th>Format</th><th>Correct / total</th><th>Accuracy</th></tr></thead><tbody>${["single","multiple","boolean","fill"].map(t=>{const a=state.attempts.filter(a=>a.question_type===t);return `<tr><td>${{single:"Single choice",multiple:"Multiple answer",boolean:"True / false",fill:"Fill in the blank"}[t]}</td><td>${a.filter(x=>x.correct).length} / ${a.length}</td><td>${a.length?accuracy(a)+"%":"Not assessed"}</td></tr>`}).join("")}</tbody></table></section><section class="panel"><h2>Accuracy by topic</h2>${topicTable()}<details class="mt"><summary>How the readiness estimate works</summary><p class="small muted">25% overall accuracy, 15% lesson completion, 15% recent accuracy, 15% hard-question accuracy, 20% average of the latest three mocks, 10% average section accuracy with at least three answers. Repeatedly incorrect concepts in the latest 100 answers subtract up to 10 points; two recent correct responses for that concept clear its repeated-error penalty. A 90+ rating additionally requires 100 recorded answers, at least five answers in each module, 15 hard answers, two mocks, at least 85% in each major domain, at least 80% on hard questions, and few repeatedly missed concepts. Missing evidence lowers or caps the estimate.</p></details></section>`}
function topicTable(){const map={};state.attempts.forEach(a=>{const k=a.section+'|'+a.topic;(map[k]||={topic:a.topic,module:a.module,a:[]}).a.push(a)});let rows=Object.values(map).sort((a,b)=>accuracy(a.a)-accuracy(b.a));return rows.length?`<table class="progress-table"><thead><tr><th>Concept</th><th>Module</th><th>Answers</th><th>Accuracy</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.topic)}</td><td>${x.module}</td><td>${x.a.length}</td><td>${accuracy(x.a)}%</td></tr>`).join('')}</tbody></table>`:empty('Answer questions to see concept-level accuracy.')}
function flashcardsOriginal(){const cards=lessons.filter(l=>flashFilter==='all'||l.module===Number(flashFilter)||l.id===flashFilter).flatMap(l=>l.concepts.map(c=>({...c,section:l.id,module:l.module,key:l.id+'|'+c.term}))).filter(c=>!flashOnlyReview||state.cards[c.key]?.known===false||state.cards[c.key]?.due<=Date.now());if(!cards.length)return `${header('Flashcards','Recall the idea before you reveal it.')}<div class="filters">${moduleSelect('flashModule')}<button class="btn secondary" data-action="flash-all">Show all cards</button></div>${empty('No cards due in this filter. Try all cards.')}`;flashIndex=Math.max(0,Math.min(flashIndex,cards.length-1));const c=cards[flashIndex];window.currentFlash=c;return `${header('Flashcards','Active recall for the definitions and distinctions that matter.')}<div class="filters">${moduleSelect('flashModule')}<button class="btn secondary small" data-action="flash-review">${flashOnlyReview?'Show all cards':'Due / need review'}</button><button class="btn secondary small" data-action="flash-random">Random card</button></div><div class="question-wrap"><div class="flash-meta"><span class="tag">MODULE ${c.module}</span> <span class="muted small">Card ${flashIndex+1} of ${cards.length}</span></div><button class="flashcard" data-action="flip" aria-label="Flip flashcard"><span class="eyebrow">${flipped?'THE EXPLANATION':'WHAT DOES THIS MEAN?'}</span><h2 class="mt">${esc(c.term)}</h2>${flipped?`<p>${esc(c.explanation)}</p>`:'<p class="muted">Think of the answer, then click to flip.</p>'}<span class="tag">${flipped?'Click to return to the concept':'Click to reveal'}</span></button><div class="actions mt" style="justify-content:center"><button class="btn secondary" data-action="flash-prev" ${flashIndex===0?'disabled':''}>← Previous</button><button class="btn soft" data-action="flash-known">${icon('check')} Known</button><button class="btn secondary" data-action="flash-need">Need review</button><button class="btn secondary" data-action="flash-next" ${flashIndex===cards.length-1?'disabled':''}>Next →</button></div><p class="muted small flash-meta">Known cards are scheduled at expanding intervals: 1, 3, 7, 14 and 30 days. Need-review cards return sooner. Scheduling and filters use your browser-local progress.</p><div class="flash-meta"><a href="#lesson/${c.section}">Open related lesson →</a></div></div>`}
const comparisons=[
['AI vs ML vs DL',['AI','Machine learning','Deep learning'],[['Scope','The broader field of intelligent systems','A way to learn patterns from experience','A neural-network-based branch of ML'],['Key distinction','Includes multiple schools and methods','Performance improves with experience','Multiple learned layers build representations'],['Common trap','Not every AI system uses ML','Not all ML is deep learning','Not a synonym for all AI']]],
['Supervised vs Unsupervised vs Reinforcement',['Supervised','Unsupervised','Reinforcement'],[['Feedback','Known targets','No supplied target labels','Rewards from interaction'],['Typical task','Classification or regression','Clustering','Learning an action strategy'],['Watch for','Labels are provided','Groups discovered from similarity','Agent, environment, actions and rewards']]],
['Classification vs Regression',['Classification','Regression'],[['Target','Discrete category','Continuous numerical quantity'],['Example','Fraud / not fraud','Predicted apartment price'],['Metrics','Accuracy, precision, recall, F1','MAE, MSE, R²'],['Trap','Numerically coded labels are still categories','A numerical input does not define regression']]],
['CNN vs RNN',['CNN','RNN'],[['Core operation','Shared local convolution filters','Recurrent state across time'],['Typical strength','Spatial feature extraction','Ordered sequential data'],['Information flow','Features across spatial layers','Current input plus previous hidden state'],['Trap','Pooling and convolution differ','Time steps have sequential dependencies']]],
['RNN vs Transformer',['RNN','Transformer'],[['Core connection','Recurrence','Attention'],['Order information','Encoded through sequence processing','Added through position information'],['Training parallelism','Limited by previous-state dependence','More parallel sequence computation'],['Trap','Hidden state is not an attention score','Autoregressive inference still generates sequentially']]],
['Pre-training vs Fine-tuning',['Pre-training','Fine-tuning'],[['Purpose','Learn broad representations','Adapt a pretrained representation'],['Typical data','Large, diverse corpus','Task- or domain-specific examples'],['Starting point','A model undergoing initial broad learning','Existing pretrained parameters'],['Trap','Not deployment','Not identical to writing a prompt']]],
['Zero-shot vs Few-shot',['Zero-shot','Few-shot'],[['Demonstrations','None','A small number'],['Input','Task instruction and new problem','Task demonstrations and new problem'],['Weights','No weight update from prompting itself','No weight update from demonstrations alone'],['Trap','Can still contain useful context','Does not automatically imply CoT']]],
['Few-shot-CoT vs Zero-shot-CoT',['Few-shot-CoT','Zero-shot-CoT'],[['Examples','Worked solution demonstrations','No worked demonstrations'],['Reasoning instruction','Steps shown in examples','Steps requested through the instruction'],['Common point','Prompt-level reasoning guidance','Prompt-level reasoning guidance'],['Trap','Not merely answer-only examples','Not few-shot just because steps are requested']]],
['PyTorch vs TensorFlow vs JAX',['PyTorch','TensorFlow','JAX'],[['Course emphasis','Python-oriented tensors and dynamic graphs','End-to-end ML platform and deployment tools','NumPy-like APIs, differentiation and XLA'],['Primary role','Framework for model development','Framework for model development','High-performance numerical computing'],['Trap','Software, not a physical accelerator','TF2 supports eager execution','A library, not a pretrained chatbot']]],
['PTH / PT vs ONNX',['PTH / PT','ONNX'],[['Role','Common PyTorch save-file extensions','Model interchange representation'],['Contents','May hold state_dict or serialized model','Exported graph representation and supported state'],['Trap','Extension alone does not say what was saved','Conversion support depends on operators and tooling']]],
['Training vs Inference',['Training','Inference'],[['Goal','Learn or adapt model parameters','Produce predictions using a model'],['Gradient use','Usually backward and parameter updates','Ordinarily no weight updates'],['PyTorch mode','train() as appropriate','eval() plus no_grad() when appropriate'],['Trap','Forward propagation also occurs in training','eval() does not itself disable autograd']]],
['Parameter vs Hyperparameter',['Parameter','Hyperparameter'],[['How determined','Learned or estimated from data','Configured or selected by a tuning process'],['Examples','Weights, biases, regression coefficients','Learning rate, batch size, fold count'],['Dataset role','Fitted using training data','Selected using validation performance'],['Trap','Not every number in a program is learned','Search can automate selection']]],
['Backpropagation vs Gradient descent',['Backpropagation','Gradient descent'],[['Purpose','Compute gradients using the chain rule','Use gradients to choose a parameter update'],['PyTorch operation','loss.backward()','optimizer.step()'],['Trap','Does not alone apply optimizer updates','Does not replace the need for gradients']]],
['Data vs Tensor vs Pipeline Parallelism',['Data parallelism','Tensor parallelism','Pipeline parallelism'],[['What is split','Training examples','Individual tensors / matrix operations','Model layers'],['Devices hold','Model replicas','Partitions of tensors','Successive layer groups'],['Coordination','Gradient synchronization','Intermediate computation communication','Stage-to-stage activations and gradients']]]
];
function compare(){const c=comparisons[compareIndex]||comparisons[0];return `${header('Make the distinction','Compare concepts side by side and clear up common exam confusions.')}<section class="panel"><label class="small muted" for="compareSelect">Choose a comparison</label><select id="compareSelect" class="field fullwidth mt">${comparisons.map((x,i)=>`<option value="${i}" ${compareIndex===i?'selected':''}>${esc(x[0])}</option>`).join('')}</select><h2 class="mt">${esc(c[0])}</h2><div style="overflow:auto"><table class="compare-table"><thead><tr><th>Aspect</th>${c[1].map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${c[2].map(row=>`<tr>${row.map((x,i)=>`<${i===0?'th':'td'}>${esc(x)}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div><div class="source-note">Study comparisons summarize the related lessons. Use course search to open the original section and its source pages.</div></section>`}
function revision(){const categories=[['Must memorize',['E = experience; T = task; P = performance.','AI ⊃ ML ⊃ DL.','Sigmoid: (0,1); tanh: (-1,1); ReLU: max(0,x).','Precision = TP/(TP+FP); recall = TP/(TP+FN).','Accuracy = (TP+TN)/(TP+TN+FP+FN).','F1 = 2×precision×recall/(precision+recall).']],['Must understand',['Training fits parameters; validation selects configurations; testing estimates generalization.','Overfitting: good training results, poor generalization.','Backpropagation computes gradients; an optimizer applies updates.','Linear layers alone remain linear; nonlinear activations add expressive power.','A larger model is not automatically the right deployment choice.']],['Algorithms and comparisons',['Logistic regression classifies; linear regression predicts numerical values.','LASSO: L1; Ridge: L2.','SVM seeks a large margin; kernels support nonlinear boundaries.','k-NN uses neighbors; k-means groups into clusters.','Bagging combines independently trained learners; boosting trains sequentially.','Random Forest: bagged trees; GBDT: boosted trees.']],['Architectures',['CNN: local receptive fields, weight sharing, convolution and pooling.','RNN: current input + previous hidden state.','LSTM: cell state, forget gate, input gate and output gate.','Seq2Seq: encoder → context → decoder; fixed context can lose long-input information.','Attention: query/key scores → softmax → weighted sum of values.','GPT-1: decoder-style; BERT: bidirectional encoder; MoE: expert routing.']],['PyTorch essentials',['Dataset defines sample access; DataLoader supplies batches.','nn.Module defines a network; forward defines data flow.','zero_grad → forward → loss → backward → step.','state_dict stores state; reconstruct a compatible model before loading.','eval changes module behavior; no_grad disables gradient recording.','.pt/.pth are common PyTorch save extensions; ONNX is an interchange format.']],['Large models and prompting',['Pretraining → fine-tuning / alignment → evaluation → deployment.','RLHF: supervised fine-tuning → human-ranked reward model → RL optimization.','LoRA trains low-rank updates; adapters add task-specific modules.','Data parallel: split data; tensor parallel: split tensors; pipeline: split layers.','Zero-shot: no demonstrations. Few-shot: demonstrations.','Few-shot-CoT: worked examples. Zero-shot-CoT: stepwise instruction without examples.']],['Numbers and source facts',['Official outline: H13-311, 90 minutes, 600/1000 passing score.','Domain weights: 10%, 20%, 30%, 20%, 15%, 5%.','Course history: McCarthy / Dartmouth, 1956; Transformer, 2017; BERT, 2018.','DeepSeek course timeline: launch 2023; V2 May 2024; V3 December 2024.','GPT-1 course example: 12 layers, 12 attention heads, 117 million parameters.','Read estimated model sizes and reported costs as dated course claims, not independently established current facts.']],['Applications and last-minute traps',['Celia: assistant; HarmonyOS: cockpit; Qiankun: intelligent driving.','Knowledge graphs connect entities and semantic relationships for recommendations.','VLA combines vision, language and action; RT-2 is the course example.','FermiNet / LapNet: quantum; GNoME / MatterGen: materials; DeePMD-kit: molecular dynamics.','AlphaFold2: protein structure prediction.','Multiple-answer questions require every correct option. Missing and extra choices both make the response incorrect.']]];return `${header('Final revision','High-yield memory rules, important distinctions and your next review priorities.')}<div class="actions" style="margin-bottom:20px"><a class="btn" href="#mistakes">Review my mistakes →</a><a class="btn secondary" href="#compare">Compare concepts</a><a class="btn secondary" href="training-material.pdf" target="_blank" rel="noopener">Open primary source ↗</a></div><div class="revision-grid">${categories.map(([title,items])=>`<section class="panel"><h2>${title}</h2><ul>${items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`).join('')}</div><section class="panel mt"><h2>Exam coverage checklist</h2><div class="checklist">${modules.map(m=>`<label><input type="checkbox" data-checkmodule="${m.id}" ${state['revision-'+m.id]?'checked':''}> Module ${m.id}: ${esc(m.title)} · ${m.weight}%</label>`).join('')}</div><div class="source-note">Study summaries are not a replacement for the full slide content. Use the source viewer in every lesson to review names, numbers, code, diagrams and caveats.</div></section>`}
function settings(){return `${header('Your workspace settings','Your learning data belongs to you. Keep a backup and pick up where you left off.')}<section class="panel"><h2>Personal preferences</h2><div class="setting-row"><div><h3>Daily study goal</h3><p>Your target minutes per day; progress is based on recorded active study time.</p></div><select id="goalSelect" class="field" aria-label="Daily study goal">${[10,15,20,30,45,60].map(v=>`<option value="${v}" ${state.goal===v?"selected":""}>${v} minutes</option>`).join("")}</select></div><div class="setting-row"><div><h3>Your name</h3><p>Used in the dashboard greeting.</p></div><input class="field" id="nameInput" value="${esc(state.name)}" maxlength="40" aria-label="Your name"></div><div class="setting-row"><div><h3>Dark mode</h3><p>Switch between light and dark learning spaces.</p></div><button class="btn secondary small" data-action="theme">${state.dark?'Use light mode':'Use dark mode'}</button></div><div class="setting-row"><div><h3>Focus mode</h3><p>A wider reading view with fewer lesson-side distractions.</p></div><button class="btn secondary small" data-action="focus">${state.focus?'Turn off':'Turn on'}</button></div></section><section class="panel"><h2>Progress and backups</h2><div class="setting-row"><div><h3>Export my progress</h3><p>Downloads completed lessons, attempts, mistakes, exams and flashcard schedules.</p></div><button class="btn secondary small" data-action="export">${icon('download')} Export JSON</button></div><div class="setting-row"><div><h3>Restore a backup</h3><p>Replaces this browser progress with a previously exported backup.</p></div><label class="btn secondary small">${icon('upload')} Import<input type="file" id="importFile" accept="application/json" hidden></label></div><div class="setting-row"><div><h3>Reset progress</h3><p>Clears this browser learning history. Export a backup first.</p></div><button class="btn secondary small" data-action="reset">Reset progress</button></div><p class="muted small mt">Progress is stored locally in this browser. It persists after reload, but is not automatically synced across devices or browser profiles. Private browsing and clearing site data can remove it. Export a JSON backup to carry your progress to another browser.</p></section><section class="panel"><h2>Publish on your own hosting</h2><p class="muted small">This site can run on any static web host. Download the standalone package, upload it to your hosting account, or drop it into Netlify Drop for an independent address. It contains no ChatGPT sign-in integration. Your learning history remains browser-local: export progress above and import it on the new address.</p><div class="actions"><a class="btn secondary small" href="fieldnotes-standalone.zip" download>Download standalone site</a><a class="btn secondary small" href="https://app.netlify.com/drop" target="_blank" rel="noopener">Open Netlify Drop ↗</a></div></section><section class="panel"><h2>Content management</h2><p class="muted small">Course content and questions are separate data files. You can export and import a validated content pack for this browser. Changes do not modify the published source for other browsers. Back up progress before removing or renaming sections.</p><div class="actions"><button class="btn secondary small" data-action="content-export">Export content pack</button><label class="btn secondary small">Import content pack<input id="contentFile" type="file" accept="application/json" hidden></label><button class="btn secondary small" data-action="content-reset">Restore published content</button></div></section><section class="panel"><h2>Sources and assessment rules</h2><p class="small">Primary content: the uploaded Huawei HCIA-AI V4.0 Training Material, 473 PDF pages. Each section provides page references and original slides. Original practice items are study aids, not leaked exam questions.</p><p class="small">Official exam-outline snapshot checked on 18 October 2026: H13-311, English / Chinese, 90 minutes, 600 / 1000, domain weighting 10 / 20 / 30 / 20 / 15 / 5. The platform mock uses 60 questions as a simulation choice.</p><p class="small">Automatic live web research is not connected in this browser-local version. Use the official links to check changes; the source PDF remains the basis for course-specific questions.</p><div class="actions"><a class="btn secondary small" href="https://e.huawei.com/en/talent/" target="_blank" rel="noopener">Huawei Talent ↗</a><a class="btn secondary small" href="https://pytorch.org/docs/stable/index.html" target="_blank" rel="noopener">PyTorch documentation ↗</a><a class="btn secondary small" href="training-material.pdf" target="_blank" rel="noopener">Uploaded training material ↗</a></div><details class="mt"><summary>[External Knowledge] Verified source clarifications</summary><ul class="small"><li>PDF p.302 quiz key conflicts with the original encoder-decoder Transformer diagram on p.290. Ambiguous wording is excluded from assessment.</li><li>PDF p.166 speaker note calls all non-root tree nodes leaves. Internal non-root nodes can have children; leaves have none.</li><li>PDF p.349 batch_first example contains an inconsistent shape comment. Interpret [5,3,10] as batch=5, sequence=3, features=10 when batch_first=True.</li><li>Slide claims about cost, estimated model sizes and capabilities are historical course statements, not current independently verified product claims.</li></ul><p class="small"><a href="https://docs.pytorch.org/docs/stable/notes/autograd" target="_blank" rel="noopener">PyTorch: evaluation mode versus gradient modes ↗</a><br><a href="https://docs.pytorch.org/docs/stable/generated/torch.nn.RNN.html" target="_blank" rel="noopener">PyTorch: RNN tensor layout ↗</a><br><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noopener">Original Transformer paper ↗</a></p><ul></ul></details></section>`}
function search(){const q=query.toLowerCase().trim();if(!q)return `${header('Search your course','Find topics, concepts, definitions and practice questions.')}<p class="muted">Type in the search field above.</p>`;const hits=lessons.filter(l=>JSON.stringify(l).toLowerCase().includes(q));const qhits=bank.filter(x=>x.question_type==='single'&&[x.question,x.topic,x.source_topic].some(t=>t.toLowerCase().includes(q))).slice(0,25);return `${header('Search results',`${hits.length} sections and ${qhits.length} question matches for “${esc(query)}”`)}<section class="panel"><h2>Sections and concepts</h2>${hits.length?hits.map(l=>`<a class="search-result" href="#lesson/${l.id}"><span class="eyebrow">MODULE ${l.module} · PDF ${l.pages.join('–')}</span><h3>${esc(l.title)}</h3><p>${esc(l.intro)}</p><span class="tag">${esc(l.concepts.filter(c=>JSON.stringify(c).toLowerCase().includes(q)).map(c=>c.term).join(' · ')||'Section match')}</span></a>`).join(''):empty('No sections found. Try another term.')}</section><section class="panel"><h2>Practice question matches</h2>${qhits.length?qhits.map(q=>`<div class="search-result"><span class="eyebrow">MODULE ${q.module} · ${esc(q.source_topic)}</span><h3>${esc(q.question)}</h3><button class="btn secondary small" data-action="practice-one:${q.question_id}">Practice this question</button></div>`).join(''):empty('No matching questions.')}</section>`}
