async function importContent(e){try{const v=JSON.parse(await e.target.files[0].text());if(!Array.isArray(v.course?.modules)||!Array.isArray(v.course?.lessons)||!Array.isArray(v.questions))throw Error('Expected course and questions arrays');if(v.course.modules.length!==6)throw Error('The course must retain six modules');const ids=new Set(v.course.lessons.map(l=>l.id));if(ids.size!==v.course.lessons.length)throw Error('Duplicate section IDs');v.course.lessons.forEach(l=>{if(!l.title||!l.intro||!l.concepts?.length||!Array.isArray(l.pages)||!v.course.modules.some(m=>m.id===l.module))throw Error('Invalid lesson');l.concepts.forEach(c=>{if(!c.term||!c.explanation)throw Error('Invalid concept')})});const qids=new Set();v.questions.forEach(q=>{if(qids.has(q.question_id)||!ids.has(q.section)||!q.question||!q.correct_answer?.length||!['single','multiple','boolean','fill'].includes(q.question_type))throw Error('Invalid question');qids.add(q.question_id);if(q.question_type!=='fill'&&(!q.options?.length||q.correct_answer.some(i=>!Number.isInteger(i)||i<0||i>=q.options.length)))throw Error('Invalid answer options')});if(!confirm('Use this content pack in this browser?'))return;localStorage.setItem(KEY+'-content',JSON.stringify(v));location.reload()}catch(err){toast('Could not import content: '+err.message)}}
